USE db_keperawatan;

INSERT INTO bank_soal (jenis_tes, topik, judul, deskripsi, pertanyaan)
VALUES ('PK1', 'Eliminasi Urine', 'Asesmen PK 1 Eliminasi Urin', 'Asesmen unit kompetensi KES.PG02.040.01 Memfasilitasi Pemenuhan Kebutuhan Eliminasi Urin.', CONVERT( USING utf8mb4))
ON DUPLICATE KEY UPDATE
    judul = VALUES(judul),
    deskripsi = VALUES(deskripsi),
    pertanyaan = VALUES(pertanyaan);

UPDATE form_ujian f
JOIN pengajuan p ON p.id = f.pengajuan_id
SET f.judul = 'Asesmen PK 1 Eliminasi Urin',
    f.deskripsi = 'Asesmen unit kompetensi KES.PG02.040.01 Memfasilitasi Pemenuhan Kebutuhan Eliminasi Urin.',
    f.pertanyaan = CONVERT( USING utf8mb4)
WHERE p.jenis_tes = 'PK1' AND p.topik = 'Eliminasi Urine';
